import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第四十三卦 夬 澤天夬 兌上乾下","description":"周易 - 第四十三卦 夬 澤天夬 兌上乾下","frontmatter":{"title":"第四十三卦 夬 澤天夬 兌上乾下","description":"周易 - 第四十三卦 夬 澤天夬 兌上乾下"},"headers":[],"relativePath":"classics/zhouyi/044.md","filePath":"classics/zhouyi/044.md"}'),l={name:"classics/zhouyi/044.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="夬" tabindex="-1">夬 <a class="header-anchor" href="#夬" aria-label="Permalink to “夬”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>揚於王庭，孚號，有厲，告自邑，不利即戎，利有攸往。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>夬，決也，剛決柔也。健而說，決而和，揚於王庭，柔乘五剛也。孚號有厲，其危乃光也。告自邑，不利即戎，所尚乃窮也。利有攸往，剛長乃終也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>澤上於天，夬；君子以施祿及下，居德則忌。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>壯於前趾，往不勝為吝。 象曰：不勝而往，咎也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>惕號，莫夜有戎，勿恤。象曰：莫夜有戎，得中道也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>壯於，有兇。君子夬夬，獨行遇雨，若濡有慍，無咎。象曰：君子夬夬，終無咎也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>臀無膚，其行次且。牽羊悔亡，聞言不信。象曰：其行次且，位不當也。聞言不信，聰不明也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>莧陸夬夬，中行無咎。象曰：中行無咎，中未光也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>無號，終有兇。象曰：無號之兇，終不可長也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
